import { NavLink, Outlet, useParams } from 'react-router-dom'
import { useQuery } from '@tanstack/react-query'
import { PageHeader } from '@/features/shell/PageHeader'
import { projectsService } from '@/integrations/supabase/projects'
import { clsx } from 'clsx'

const PROJECT_TABS = [
  { path: 'organiser', label: 'Organiser' },
  { path: 'navigator', label: 'Navigator' },
  { path: 'goals', label: 'Goals' },
  { path: 'dashboard', label: 'Dashboard' },
  { path: 'rewards', label: 'Rewards' },
  { path: 'settings', label: 'Settings' },
]

export function ProjectLayout() {
  const { projectId } = useParams()
  const { data: project } = useQuery({
    queryKey: ['project', projectId],
    queryFn: () => projectsService.getProject(projectId ?? ''),
    enabled: !!projectId,
  })

  return (
    <div className="flex flex-col h-full overflow-hidden">
      <PageHeader title={project?.title ?? 'Project'} subtitle="Project workspace" />
      <nav className="flex gap-0 border-b border-border px-4 bg-surface shrink-0 overflow-x-auto">
        {PROJECT_TABS.map((tab) => (
          <NavLink key={tab.path} to={`/app/project/${projectId}/${tab.path}`}
            className={({ isActive }) => clsx('px-4 py-2.5 text-sm whitespace-nowrap border-b-2 transition-colors',
              isActive ? 'border-accent text-accent font-medium' : 'border-transparent text-muted-foreground hover:text-foreground')}>
            {tab.label}
          </NavLink>
        ))}
      </nav>
      <div className="flex-1 overflow-hidden"><Outlet /></div>
    </div>
  )
}
